// 四個流程的虛構示範資料（全部為虛構姓名、案號、編號與地址）。
// 每組資料都刻意埋入幾個應被找出的錯誤，以及幾個「不應誤報」的情境。

import { buildDocx, buildPdf, buildZip, fakeId, para, type DBlock } from './builders';
import { writeXlsx } from '../../src/core/xlsx';

export interface DemoFile {
  name: string;
  data: Uint8Array;
}

// ===================== 流程 A =====================
// 埋入：陳美玲通知函把「司執助」寫成「司執」；林志豪通知函支票備註案號誤植。
// 不應誤報：法院公文未記載銀行帳號、身分證僅遮罩（部分核對）、林志豪法院公文未載金額。
// 法院公文頁序與通知函頁序刻意不同，驗證不以頁序配對。
export async function demoA(): Promise<DemoFile[]> {
  const idWang = fakeId('A', '12345678');
  const letter = await buildDocx([
    [
      para('甲電信股份有限公司　通知函'),
      para('主旨：檢送【臺灣臺北地方法院】【114年度司執字第12345號】執行命令，債務人【王小明】債權金額新臺幣【15,520】元，請查照。'),
      para(`債務人：【王小明】　身分證統一編號：【${idWang}】`),
      para('支票備註：【114年度司執字第12345號】【王小明】'),
      para('匯款帳號：0123456789012'),
      para('附件：臺灣臺北地方法院執行命令影本乙份'),
    ],
    [
      para('甲電信股份有限公司　通知函'),
      { runs: [{ text: '主旨：檢送' }, { text: '臺灣臺北地方法院', styleRed: true }, { text: '114年度司執字第2345號', styleRed: true }, { text: '執行命令，債務人' }, { text: '陳美玲', styleRed: true }, { text: '，請查照。' }] },
      para('債務人：【陳美玲】'),
      para('支票備註：【114年度司執字第2345號】【陳美玲】'),
      para('附件：執行命令影本乙份'),
    ],
    [
      para('甲電信股份有限公司　通知函'),
      para('主旨：檢送【臺灣新北地方法院】【114年度司執字第34567號】執行命令，債務人【林志豪】，請查照。'),
      para('債務人：【林志豪】'),
      para('支票備註：【114年度司執字第34576號】【林志豪】'),
      para('附件：執行命令影本乙份'),
    ],
  ]);
  const court = buildPdf([
    {
      lines: [
        '臺灣新北地方法院　執行命令',
        '發文日期：中華民國114年8月6日',
        '發文字號：新北院英114司執玄字第88001號',
        '受文者：甲電信股份有限公司',
        '主旨：債權人甲電信股份有限公司與債務人林志豪間114年度司執字第34567號',
        '給付電信費強制執行事件，禁止債務人收取對第三人之債權。',
        '債務人：林志豪',
      ],
    },
    {
      lines: [
        '臺灣臺北地方法院　執行命令',
        '發文日期：中華民國114年8月5日',
        '發文字號：北院英114司執玄字第77001號',
        '受文者：甲電信股份有限公司',
        '主旨：債權人甲電信股份有限公司與債務人王小明間114年度司執字第12345號',
        '給付電信費強制執行事件，債權金額新臺幣15,520元。',
        `債務人：王小明　身分證統一編號：${idWang.slice(0, 5)}*****`,
      ],
    },
    { lines: ['（續前頁）說明：', '一、本命令送達後，第三人應依強制執行法第一百十五條辦理。', '二、如有異議，應於十日內聲明。'] },
    {
      lines: [
        '臺灣臺北地方法院　執行命令',
        '發文日期：中華民國114年8月7日',
        '發文字號：北院英114司執玄字第77002號',
        '受文者：甲電信股份有限公司',
        '主旨：債權人甲電信股份有限公司與債務人陳美玲間114年度司執助字第2345號',
        '給付電信費強制執行事件。',
        '債務人：陳美玲',
      ],
    },
  ]);
  return [
    { name: '前端通知函_114年8月.docx', data: letter },
    { name: '法院執行命令_合併掃描.pdf', data: court },
  ];
}

// ===================== 流程 B =====================
// 埋入：書狀地址與支付命令不同（列人工確認，不直接判錯）。
// 驗證：寄存送達 114/7/1 → 114/7/12 起息；15,520 − 1,244 = 14,276；國字＝數字。
export async function demoB(): Promise<DemoFile[]> {
  const id = fakeId('F', '22334455');
  const petition = await buildDocx([
    [
      para('民事強制執行聲請狀'),
      para('債權人：甲電信股份有限公司　設臺北市信義區信義路五段7號'),
      para(`債務人：周雅婷　身分證統一編號：${id}`),
      para('住所：新北市板橋區文化路一段188號6樓'),
      para('執行名義：臺灣士林地方法院114年度司促字第8888號支付命令及確定證明書。'),
      para('請求金額：本金新臺幣15,520元，扣除已清償1,244元，尚欠新臺幣壹萬肆仟貳佰柒拾陸元（14,276元）。計算式：15,520 - 1,244 = 14,276。'),
      para('及自114年7月12日起至清償日止，按週年利率百分之五計算之利息，並督促程序費用新臺幣500元。'),
      para('附件一：支付命令正本一份'),
      para('附件二：確定證明書一份'),
      para('此致　臺灣新北地方法院民事執行處'),
    ],
  ]);
  const merged = buildPdf([
    {
      lines: [
        '臺灣士林地方法院支付命令',
        '114年度司促字第8888號',
        '債權人：甲電信股份有限公司',
        `債務人：周雅婷　身分證統一編號：${id}`,
        '住所：新北市板橋區文化路一段168號6樓',
        '債務人應向債權人清償新臺幣15,520元，及自本支付命令送達翌日起至清償日止，',
        '按週年利率百分之五計算之利息，並賠償督促程序費用新臺幣500元，',
        '否則應於本命令送達後二十日之不變期間內，向本院提出異議。',
      ],
    },
    { lines: ['臺灣士林地方法院支付命令確定證明書', '114年度司促字第8888號', '上開支付命令已於114年8月1日確定。', '中華民國114年8月15日'] },
    { lines: ['送達證書', '114年度司促字第8888號', '應受送達人：周雅婷', '送達方式：未獲會晤本人亦無受領文書之同居人，已將文書寄存於板橋派出所', '寄存日期：114年7月1日'] },
  ]);
  return [
    { name: '民事強制執行聲請狀_周雅婷.docx', data: petition },
    { name: '執行名義合併檔.pdf', data: merged },
  ];
}

// ===================== 流程 C =====================
// 11 位債務人：戶籍謄本合併 10 頁（缺 1 人）、2 人同名、1 份帳單只有「本期應繳」、
// 1 份有已繳款（金額待釐清）、1 份地址樓層不同、1 份帳務 PDF 為掃描影像。
interface CPerson {
  serial: string;
  name: string;
  id: string;
  addr: string;
  petAddr?: string;
  amount: number;
  stAmount?: number;
  onlyCurrentBill?: boolean;
  paid?: number;
  scanned?: boolean;
  noHousehold?: boolean;
  phone: string;
}

const C_PEOPLE: CPerson[] = [
  { serial: '70010001', name: '王小明', id: fakeId('A', '12345671'), addr: '臺北市中正區重慶南路一段100號5樓', amount: 12345, phone: '0912345601' },
  { serial: '70010002', name: '李佩珊', id: fakeId('B', '22345672'), addr: '臺中市西區民權路200號', amount: 8800, phone: '0912345602' },
  { serial: '70010003', name: '張家豪', id: fakeId('E', '12345673'), addr: '高雄市苓雅區四維三路2號3樓', amount: 21000, petAddr: '高雄市苓雅區四維三路2號5樓', phone: '0912345603' },
  { serial: '70010004', name: '黃怡君', id: fakeId('H', '22345674'), addr: '桃園市桃園區中正路99號', amount: 5600, onlyCurrentBill: true, phone: '0912345604' },
  { serial: '70010005', name: '王小明', id: fakeId('F', '12345675'), addr: '新北市三重區重新路三段8號', amount: 9900, phone: '0912345605' },
  { serial: '70010006', name: '吳宗翰', id: fakeId('D', '12345676'), addr: '臺南市東區東門路二段50號', amount: 15000, stAmount: 16200, paid: 1200, phone: '0912345606' },
  { serial: '70010007', name: '蔡依婷', id: fakeId('C', '22345677'), addr: '基隆市仁愛區愛一路3號', amount: 4300, scanned: true, phone: '0912345607' },
  { serial: '70010008', name: '劉建宏', id: fakeId('J', '12345678'), addr: '新竹縣竹北市光明六路10號', amount: 7700, noHousehold: true, phone: '0912345608' },
  { serial: '70010009', name: '許淑芬', id: fakeId('K', '22345679'), addr: '苗栗縣苗栗市中正路1號', amount: 6600, phone: '0912345609' },
  { serial: '70010010', name: '鄭志明', id: fakeId('M', '12345670'), addr: '南投縣南投市中興路5號', amount: 3100, phone: '0912345610' },
  { serial: '70010011', name: '謝雅雯', id: fakeId('N', '22345671'), addr: '彰化縣彰化市中山路二段6號', amount: 11100, phone: '0912345611' },
];

export async function demoC(): Promise<DemoFile[]> {
  const files: Record<string, Uint8Array> = {};
  for (const p of C_PEOPLE) {
    const amt = p.amount.toLocaleString('en-US');
    files[`聲請狀/支付命令聲請狀_${p.serial}.pdf`] = buildPdf([
      {
        lines: [
          '民事支付命令聲請狀',
          `案件編號：${p.serial}`,
          '債權人：甲電信股份有限公司',
          `債務人：${p.name}`,
          `身分證統一編號：${p.id}`,
          `住所：${p.petAddr ?? p.addr}`,
          `請求金額：新臺幣${amt}元`,
          `債務人應給付債權人新臺幣${amt}元，及自支付命令送達翌日起至清償日止，`,
          '按週年利率百分之五計算之利息。（欠費計算至114年6月30日）',
          `門號：${p.phone}`,
        ],
      },
    ]);
    const st = (p.stAmount ?? p.amount).toLocaleString('en-US');
    files[`帳務/${p.serial}.pdf`] = buildPdf([
      p.scanned
        ? { lines: [], scanned: true }
        : {
            lines: [
              '電信欠費明細',
              `客戶編號：${p.serial}`,
              `用戶姓名：${p.name}`,
              `門號：${p.phone}`,
              '計算至114年6月30日',
              ...(p.onlyCurrentBill ? [`本期應繳新臺幣${st}元`] : [`總欠費新臺幣${st}元`]),
              ...(p.paid ? [`已繳金額新臺幣${p.paid.toLocaleString('en-US')}元`] : []),
            ],
          },
    ]);
  }
  // 合併戶籍謄本：10 頁（劉建宏缺頁）；第一頁含戶長（家屬）資料
  const pages = C_PEOPLE.filter((p) => !p.noHousehold).map((p, i) => ({
    lines: [
      '戶籍謄本（現戶部分）',
      `戶籍地址：${p.addr}`,
      ...(i === 0 ? [`稱謂：戶長　姓名：王大同　統一編號：${fakeId('A', '10000001')}　出生日期：民國50年1月1日`] : []),
      `稱謂：${i === 0 ? '子' : '本人'}　姓名：${p.name}　統一編號：${p.id}　出生日期：民國80年5月5日`,
    ],
  }));
  files['戶籍謄本_合併.pdf'] = buildPdf(pages);
  const zip = await buildZip(files);
  return [{ name: '支付命令批次_114年7月.zip', data: zip }];
}

// ===================== 流程 D =====================
// 埋入：附件二「帳單」書狀記載兩份，附件 PDF 只有一份；附件三債務明細表未收入附件 PDF。
// 驗證：Excel 30,802＝參萬零捌佰零貳元整＝NT$30,802；庭函為限期陳報，不比對開庭日期；
//       庭函發文字號不當作案號；「陳美玲即陳美鈴」別名。
export async function demoD(): Promise<DemoFile[]> {
  const letter = buildPdf([
    {
      lines: [
        '臺灣臺北地方法院民事庭　函',
        '發文日期：中華民國114年9月1日',
        '發文字號：北院英民丁114北簡1234字第1140012345號',
        '受文者：甲電信股份有限公司',
        '主旨：本院114年度北簡字第1234號（丁股）給付電信費事件，',
        '請於文到七日內具狀陳報債務人陳美玲即陳美鈴之欠費計算明細及相關證明文件。',
      ],
    },
  ]);
  const report = await buildDocx([
    [
      para('民事陳報狀'),
      para('案號：114年度北簡字第1234號（丁股）'),
      para('原告：甲電信股份有限公司'),
      para('被告：陳美玲'),
      para('為依臺灣臺北地方法院114年9月1日函陳報事：'),
      para('一、債務人陳美玲積欠電信費用，截至114年8月31日止，未償債務共計新臺幣參萬零捌佰零貳元整（30,802元），明細如附表。'),
      { table: [['門號', '未償債務'], ['0912345678', '27,600'], ['0987654321', '3,202'], ['合計', '30,802']] },
      para('附件一：行動寬頻申請書影本一份'),
      para('附件二：帳單影本二份'),
      para('附件三：債務明細表一份'),
      para('此致　臺灣臺北地方法院民事庭'),
    ],
  ]);
  const xlsx = await writeXlsx([
    {
      name: '債務明細',
      header: true,
      rows: [
        ['門號', '電信資費', '代收費用', '專案補貼款', '其他應收', '已繳款', '未償債務'],
        ['0912345678', 12000, 800, 15000, 0, 200, { f: 'B2+C2+D2+E2-F2', v: 27600 }],
        ['0987654321', 2500, 702, 0, 0, 0, { f: 'B3+C3+D3+E3-F3', v: 3202 }],
        ['合計', { f: 'SUM(B2:B3)', v: 14500 }, { f: 'SUM(C2:C3)', v: 1502 }, { f: 'SUM(D2:D3)', v: 15000 }, { f: 'SUM(E2:E3)', v: 0 }, { f: 'SUM(F2:F3)', v: 200 }, { f: 'SUM(G2:G3)', v: 30802 }],
      ],
      colWidths: [14, 12, 12, 12, 12, 12, 12],
    },
  ]);
  const attach = buildPdf([
    { lines: ['附件一　申裝書', '行動寬頻業務申請書（影本）', '申請人：陳美玲'] },
    { lines: ['附件二　帳單', '114年5月份電信帳單（影本）'] },
  ]);
  const apply = buildPdf([{ lines: ['行動寬頻申請書', '申請人：陳美玲', '門號：0912345678'] }]);
  const bill1 = buildPdf([{ lines: ['電信帳單', '114年5月份', '本期應繳新臺幣3,100元'] }]);
  const bill2 = buildPdf([{ lines: ['電信帳單', '114年6月份', '本期應繳新臺幣3,202元'] }]);
  const zip = await buildZip({
    '法院民事庭函.pdf': letter,
    '民事陳報狀.docx': report,
    '債務明細表.xlsx': xlsx,
    '陳報狀附件.pdf': attach,
    '申裝書+帳單/行動寬頻申請書.pdf': apply,
    '申裝書+帳單/帳單_11405.pdf': bill1,
    '申裝書+帳單/帳單_11406.pdf': bill2,
  });
  return [{ name: '民事陳報_陳美玲.zip', data: zip }];
}

export type { DBlock };
